#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const int MAXN = 5007;
const ll INF = 1e9;
const ll MOD = 1e9 + 7;

struct Edge {
    int from, to;
    ll cap, cost, flow;
    Edge(int a, int b, ll c, ll d) : from(a), to(b), cap(c), cost(d), flow(0) {}
};

vector<Edge> edges;
vector<int> adj[MAXN];
ll dist[MAXN], potential[MAXN];
int parent[MAXN];

void add_edge(int u, int v, ll cap, ll cost) {
    adj[u].push_back(edges.size());
    edges.push_back({u, v, cap, cost});
    adj[v].push_back(edges.size());
    edges.push_back({v, u, 0, -cost});
}

void ford_bellman(int s, int n) {
    for (int i = 0; i < MAXN; i++) potential[i] = INF;
    potential[s] = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < (int)edges.size(); j++) {
            Edge &e = edges[j];
            if (e.cap == e.flow) continue;
            if (potential[e.from] == INF) continue;
            potential[e.to] = min(potential[e.to], potential[e.from] + e.cost);
        }
    }
}

void dijkstra(int s) {
    for (int i = 0; i < MAXN; i++) dist[i] = INF;
    dist[s] = 0;
    set<pair<ll, int>> pq;
    pq.insert({0, s});
    while (!pq.empty()) {
        int v = pq.begin()->second;
        pq.erase(pq.begin());
        for (int i = 0; i < (int)adj[v].size(); i++) {
            int eid = adj[v][i];
            Edge &e = edges[eid];
            if (e.cap == e.flow) continue;
            int to = e.to;
            ll len = e.cost + potential[v] - potential[to];
            if (dist[v] + len < dist[to]) {
                pq.erase({dist[to], to});
                dist[to] = dist[v] + len;
                parent[to] = eid;
                pq.insert({dist[to], to});
            }
        }
    }
}

pair<ll, ll> mincost_maxflow(int s, int t) {
    ford_bellman(s, 50);
    dijkstra(s);
    ll flow = 0, cost = 0;
    while (true) {
        if (dist[t] == INF) break;
        ll pushed = INF, sum = 0;
        for (int v = t; v != s; v = edges[parent[v]].from) {
            int eid = parent[v];
            pushed = min(pushed, edges[eid].cap - edges[eid].flow);
            sum += edges[eid].cost;
        }
        flow += pushed;
        cost += pushed * sum;
        for (int v = t; v != s; v = edges[parent[v]].from) {
            int eid = parent[v];
            edges[eid].flow += pushed;
            edges[eid ^ 1].flow -= pushed;
        }
        dijkstra(s);
        for (int i = 0; i < MAXN; i++) potential[i] = dist[i];
    }
    return {cost, flow};
}

void solve() {
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    vector<int> cnt(n, 0);
    for (int i = 0; i < k; i++) {
        int x;
        cin >> x;
        cnt[--x]++;
    }
    for (int i = 0; i < n; i++) {
        add_edge(5000, i, cnt[i], 0);
    }
    for (int t = 0; t < m; t++) {
        int u, v;
        cin >> u >> v;
        u--, v--;
        for (int i = 0; i < 99; i++) {
            ll cur = d;
            for (int j = 0; j < 50; j++) {
                add_edge(u + i * 50, v + (i + 1) * 50, 1, cur);
                add_edge(v + i * 50, u + (i + 1) * 50, 1, cur);
                cur += 2 * d;
            }
        }
    }
    for (int i = 0; i <= 99; i++) {
        add_edge(0 + i * 50, 5001, INF, c * i);
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 99; j++) {
            add_edge(i + j * 50, i + (j + 1) * 50, INF, 0);
        }
    }
    auto res = mincost_maxflow(5000, 5001);
    assert(res.second == k);
    cout << res.first;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    cout << fixed << setprecision(20);
    solve();
    return 0;
}
